using FluentValidation;namespace Namaa.Application.PurchaseInvoices.Commands.CreatePurchaseInvoice;public sealed class CreatePurchaseInvoiceCommandValidator:AbstractValidator<CreatePurchaseInvoiceCommand>{public CreatePurchaseInvoiceCommandValidator(){RuleFor(x=>x.PurchaseInvoiceNumber).NotEmpty().MaximumLength(30);RuleFor(x=>x.CreatedByUserId).GreaterThan(0);RuleFor(x=>x.DueDate).GreaterThanOrEqualTo(x=>x.IssueDate).When(x=>x.DueDate.HasValue);}}
